s://www.idealista.com/en/inmueble/106992887/\",image:null,isNew:true,highlight:true,notes:\"\u2b50 New find, good value \u2014 4 bed / 231 m\u00b2 for all-in ~\u20ac638.3k. \u26a0\ufe0f Detail page bot-blocked today; pool assumed from search filter, garage/orientation unconfirmed.\"},\n  {id:\"id-110462168\",title:\"Contemporary 3-bed villa, sea views \u2014 Cometa-Carri\u00f3, Calpe\",price:650000,priceAllIn:721500,bedrooms:3,bathrooms:null,size:225,plot:null,location:\"Cometa-Carri\u00f3, Calpe\",area:\"Calpe\",yearBuilt:null,orientation:\"\u2014\",pool:true,garage:\"Parking (type unverified)\",features:[\"Contemporary design\", \"Sea views\", \"225 m\u00b2\"],source:\"Idealista\",alsoListedOn:[],url:\"https://www.idealista.com/en/inmueble/110462168/\",image:null,isNew:true,highlight:false,notes:\"New find \u2014 contemporary style, all-in ~\u20ac721.5k. \u26a0\ufe0f Detail page bot-blocked today; pool assumed from search filter, garage/orientation unconfirmed.\"},\n  {id:\"id-109772055\",title:\"Renovated 5-bed villa, 500m to beach \u2014 Cometa-Carri\u00f3, Calpe\",price:749000,priceAllIn:831390,bedrooms:5,bathrooms:null,size:271,plot:null,location:\"Cometa-Carri\u00f3, Calpe\",area:\"Calpe\",yearBuilt:null,orientation:\"\u2014\",pool:true,garage:\"Parking (type unverified)\",features:[\"Magnificently renovated\", \"500m to beach\", \"271 m\u00b2 \u2014 ideal band\"],source:\"Idealista\",alsoListedOn:[],url:\"https://www.idealista.com/en/inmueble/109772055/\",image:null,isNew:true,highlight:false,notes:\"New find, near ceiling \u2014 5 bed / 271 m\u00b2, all-in ~\u20ac831.4k, close to beach. \u26a0\ufe0f Detail page bot-blocked today; pool assumed from search filter, garage/orientation unconfirmed.\"}\n];\n\n/* ---------- App ---------- */\nconst AREAS = [\"J\u00e1vea\",\"Moraira\",\"Benitachell\",\"Calpe\",\"Benissa\"];\nconst favs = new Set(JSON.parse(localStorage.getItem(FAV_KEY) || \"[]\"));\nconst state = {areas:new Set(), maxPrice:0, minBeds:0, minSize:0, sort:\"price-asc\", q:\"\", garageOnly:false, budgetOnly:false, favOnly:false};\nconst euro = n => n==null ? \"\u2014\" : \"\u20ac\"+n.toLocaleString(\"en-GB\");\nconst hasGarage = p => /garage|garaje|car ?port/i.test(p.garage||\"\") ;\n\ndocument.getElementById(\"updated\").textContent = new Date(LAST_UPDATED).toLocaleDateString(\"en-GB\",{day:\"numeric\",month:\"long\",year:\"numeric\"});\n\nconst areasEl = document.getElementById(\"areas\");\nAREAS.forEach(a=>{\n  const b=document.createElement(\"span\"); b.className=\"pill\"; b.textContent=a;\n  b.onclick=()=>{ b.classList.toggle(\"on\"); state.areas.has(a)?state.areas.delete(a):state.areas.add(a); render(); };\n  areasEl.appendChild(b);\n});\nconst bind=(id,key,fn)=>{const el=document.getElementById(id);el.addEventListener(el.type===\"checkbox\"?\"change\":\"input\",()=>{state[key]=fn?fn(el):(el.type===\"checkbox\"?el.checked:el.value);render();});};\nbind(\"maxPrice\",\"maxPrice\",el=>+el.value);\nbind(\"minBeds\",\"minBeds\",el=>+el.value);\nbind(\"minSize\",\"minSize\",el=>+el.value);\nbind(\"sort\",\"sort\");\nbind(\"q\",\"q\");\nbind(\"garageOnly\",\"garageOnly\");\nbind(\"budgetOnly\",\"budgetOnly\");\nbind(\"favOnly\",\"favOnly\");\n\nfunction passes(p){\n  if(state.areas.size && !state.areas.has(p.area)) return false;\n  if(state.maxPrice && p.priceAllIn > state.maxPrice) return false;\n  if(state.minBeds && p.bedrooms < state.minBeds) return false;\n  if(state.minSize && (p.size||0) < state.minSize) return false;\n  if(state.garageOnly && !hasGarage(p)) return false;\n  if(state.budgetOnly && p.priceAllIn > 850000) return false;\n  if(state.favOnly && !favs.has(p.id)) return false;\n  if(state.q){\n    const t=(p.title+\" \"+p.location+\" \"+p.area+\" \"+p.source+\" \"+p.features.join(\" \")+\" \"+p.notes).toLowerCase();\n    if(!t.includes(state.q.toLowerCase())) return false;\n  }\n  return true;\n}\nfunction sortFn(a,b){\n  switch(state.sort){\n    case \"price-desc\": return b.priceAllIn-a.priceAllIn;\n    case \"size-desc\": return (b.size||0)-(a.size||0);\n    case \"plot-asc\": return (a.plot||1e9)-(b.plot||1e9);\n    case \"new\": return (b.isNew?1:0)-(a.isNew?1:0) || a.priceAllIn-b.priceAllIn;\n    default: return a.priceAllIn-b.priceAllIn;\n  }\n}\nfunction toggleFav(id){\n  favs.has(id)?favs.delete(id):favs.add(id);\n  localStorage.setItem(FAV_KEY, JSON.stringify([...favs]));\n  render();\n}\nfunction card(p){\n  const over = p.priceAllIn>850000;\n  const el=document.createElement(\"article\"); el.className=\"card\";\n  el.onclick=()=>window.open(p.url,\"_blank\",\"noopener\");\n  const img = p.image\n    ? `<img loading=\"lazy\" src=\"${p.image}\" alt=\"\" onerror=\"this.parentNode.innerHTML='&lt;div class=\\\\'noimg\\\\'&gt;No photo \u2014 view listing&lt;/div&gt;'\">`\n    : `<div class=\"noimg\">No photo \u2014 view listing</div>`;\n  const also = p.alsoListedOn && p.alsoListedOn.length ? ` \u00b7 <span class=\"also\">also: ${p.alsoListedOn.join(\", \")}</span>` : \"\";\n  el.innerHTML = `\n    <div class=\"imgwrap\">\n      ${img}\n      <div class=\"badges\">\n        <span class=\"badge area\">${p.area}</span>\n        ${p.isNew?'<span class=\"badge new\">NEW</span>':''}\n        ${over?'<span class=\"badge over\">OVER BUDGET</span>':''}\n      </div>\n      <button class=\"fav ${favs.has(p.id)?'on':''}\" title=\"Save favourite\">${favs.has(p.id)?'\u2665':'\u2661'}</button>\n    </div>\n    <div class=\"body\">\n      <div class=\"price\"><b>${euro(p.price)}</b><span class=\"allin\">\u2248 ${euro(p.priceAllIn)} all-in</span></div>\n      <div class=\"title\">${p.title}</div>\n      <div class=\"specs\">\n        <span><b>${p.bedrooms}</b> bed</span>\n        <span><b>${p.bathrooms??'\u2014'}</b> bath</span>\n        <span><b>${p.size??'\u2014'}</b> m\u00b2</span>\n        <span>plot <b>${p.plot??'\u2014'}</b></span>\n        <span>${p.orientation&&p.orientation!=='\u2014'?'\u2600 '+p.orientation:''}</span>\n      </div>\n      <div class=\"chips\">\n        ${p.pool?'<span class=\"chip gold\">Pool</span>':''}\n        ${hasGarage(p)?'<span class=\"chip\">Garage</span>':''}\n        ${p.yearBuilt?'<span class=\"chip\">Built '+p.yearBuilt+'</span>':''}\n        ${p.features.slice(0,3).map(f=>'<span class=\"chip\">'+f+'</span>').join('')}\n      </div>\n      ${p.notes?`<div class=\"note\">${p.notes}</div>`:''}\n      <div class=\"foot\">\n        <span class=\"src\">${p.source}${also}</span>\n        <a class=\"view\" href=\"${p.url}\" target=\"_blank\" rel=\"noopener\" onclick=\"event.stopPropagation()\">View listing \u2192</a>\n      </div>\n    </div>`;\n  el.querySelector(\".fav\").onclick=e=>{e.stopPropagation();toggleFav(p.id);};\n  return el;\n}\nfunction render(){\n  const grid=document.getElementById(\"grid\"); grid.innerHTML=\"\";\n  const list=properties.filter(passes).sort(sortFn);\n  document.getElementById(\"empty\").style.display=list.length?\"none\":\"block\";\n  list.forEach(p=>grid.appendChild(card(p)));\n  renderStats(list.length);\n}\nfunction renderStats(shown){\n  const inBudget=properties.filter(p=>p.priceAllIn<=850000).length;\n  const byArea=AREAS.map(a=>a+\": \"+properties.filter(p=>p.area===a).length).join(\" \u00b7 \");\n  document.getElementById(\"stats\").innerHTML=`\n    <div class=\"stat\"><b>${properties.length}</b><span>villas tracked</span></div>\n    <div class=\"stat\"><b>${inBudget}</b><span>within \u20ac850k all-in</span></div>\n    <div class=\"stat\"><b>${favs.size}</b><span>your favourites</span></div>\n    <div class=\"stat\" style=\"min-width:auto\"><b style=\"font-size:12px;font-weight:500\">${byArea}</b><span>by area</span></div>`;\n}\nrender();\n</script>\n</body>\n</html>\n";

addEventListener('fetch', event => {
  event.respondWith(handleRequest(event.request));
});

async function handleRequest(request) {
  const url = new URL(request.url);
  if (url.pathname === '/' || url.pathname === '/index.html') {
    return new Response(HTML, {
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        'Cache-Control': 'no-cache, no-store, must-revalidate'
      }
    });
  }
  return new Response('Not found', { status: 404 });
}
